/**
 * Enum constants to specify SciChartSurface type
 */
export declare enum ESurfaceType {
    /**
     * A 2D Cartesian {@link SciChartSurface}
     */
    SciChartSurfaceType = "SciChartSurfaceType",
    /**
     * A 2D Polar {@link SciChartPolarSurface}
     */
    SciChartPolarSurfaceType = "SciChartPolarSurfaceType",
    /**
     * A 3D Cartesian {@link SciChart3DSurface}
     */
    SciChart3DSurfaceType = "SciChart3DSurfaceType",
    /**
     * A SVG only {@link SciChartPieSurface}
     */
    SciChartPieSurfaceType = "SciChartPieSurfaceType"
}
/** @ignore */
export declare function getIs2DSurfaceType(type: ESurfaceType): true | ESurfaceType.SciChartPolarSurfaceType;
/** @ignore */
export declare function getIs3DSurfaceType(type: ESurfaceType): boolean;
